<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import VChart from 'vue-echarts'
import {use} from 'echarts/core';import {CanvasRenderer} from 'echarts/renderers';import {BarChart} from 'echarts/charts';import {GridComponent,TooltipComponent,LegendComponent,TitleComponent} from 'echarts/components';use([CanvasRenderer,BarChart,GridComponent,TooltipComponent,LegendComponent,TitleComponent])
import {useDashboardStore} from '../stores/dashboard'
import {baseMatch,filteredValue,groupWeighted,pct,rpFull,rpShort,type Project} from '../lib/data'
const s=useDashboardStore();onMounted(s.load)
const advanced=ref(false),sourceMode=ref<'sumber'|'program'>('sumber'),showAllSources=ref(false),dimension=ref<'Fakultas'|'Program Studi'|'Bidang THE'>('Fakultas'),query=ref(''),lecturerQuery=ref(''),sortKey=ref('value'),sortDir=ref(-1),page=ref(1),pageSize=10
watch(()=>JSON.stringify(s.filters),()=>page.value=1)
const faculties=computed(()=>[...new Set(s.data?.projects.flatMap(p=>p.faculties)||[])].sort()),prodis=computed(()=>[...new Set((s.data?.projects||[]).filter(p=>s.filters.faculty==='Semua'||p.faculties.includes(s.filters.faculty)).flatMap(p=>p.prodis))].sort())
const sources=computed(()=>[...new Set(s.data?.components.map(c=>c.sourceStandard)||[])].sort()),subjects=computed(()=>[...new Set(s.data?.components.map(c=>c.subject)||[])].sort())
const contextual=computed(()=>s.filters.faculty!=='Semua'||s.filters.prodi!=='Semua')
const kpiLabel=computed(()=>contextual.value?'Pendanaan Terpetakan (Atribusi Proporsional)':'Total Pendapatan Penelitian')
const yoy=computed(()=>{if(!s.data||s.filters.year!==2025)return null;const f={...s.filters,year:2024};const prev=filteredValue(s.data.components,s.data.projects,f);return prev?{value:s.total-prev,rate:(s.total-prev)/prev*100}:null})
const annualOption=computed(()=>{if(!s.data)return{};const vals=(year:number,cat:string)=>filteredValue(s.data!.components,s.data!.projects,{...s.filters,year,category:'Semua'},cat);const ind=[vals(2024,'Industri'),vals(2025,'Industri')],non=[vals(2024,'Non-Industri'),vals(2025,'Non-Industri')];return{animationDuration:500,tooltip:{trigger:'axis',formatter:(ps:any[])=>{const i=ps[0].dataIndex,total=ind[i]+non[i];return `<b>${2024+i}</b><br>${ps.map(p=>`${p.marker}${p.seriesName}: ${rpFull(p.value)} (${pct(total?p.value/total*100:0)})`).join('<br>')}<br><b>Total: ${rpFull(total)}</b>`}},legend:{top:0},grid:{left:54,right:22,top:46,bottom:36},xAxis:{type:'category',data:['2024','2025']},yAxis:{type:'value',axisLabel:{formatter:(v:number)=>rpShort(v).replace('Rp','')}},series:[{name:'Industri',type:'bar',stack:'total',data:ind,itemStyle:{color:'#e09132',opacity: s.filters.category==='Semua'||s.filters.category==='Industri'?1:.25}},{name:'Non-Industri',type:'bar',stack:'total',data:non,itemStyle:{color:'#1d7a5d',opacity:s.filters.category==='Semua'||s.filters.category==='Non-Industri'?1:.25},label:{show:true,position:'top',formatter:(p:any)=>rpShort(ind[p.dataIndex]+non[p.dataIndex])}}]}})
function annualClick(e:any){s.filters.year=Number(e.name);s.filters.category=e.seriesName}
const sourceRows=computed(()=>((sourceMode.value==='sumber'?s.sources:s.programs).slice(0,showAllSources.value?999:10)))
const rankingOption=computed(()=>{const d=[...sourceRows.value].reverse();return{tooltip:{trigger:'axis',axisPointer:{type:'shadow'},formatter:(p:any[])=>`${p[0].name}<br>${rpFull(p[0].value)}`},grid:{left:150,right:28,top:8,bottom:28},xAxis:{type:'value',axisLabel:{formatter:(v:number)=>rpShort(v).replace('Rp','')}},yAxis:{type:'category',data:d.map(x=>x.name),axisLabel:{width:135,overflow:'truncate'}},series:[{type:'bar',data:d.map(x=>x.value),itemStyle:{color:'#2d6a8a',borderRadius:[0,5,5,0]}}]}})
function sourceClick(e:any){if(sourceMode.value==='sumber')s.filters.source=e.name}
const dimensionRows=computed(()=>{if(!s.data)return[];if(dimension.value==='Bidang THE')return groupWeighted(s.data.components,s.data.projects,s.filters,c=>c.subject);const map=new Map<string,number>();for(const p of s.projects){for(const x of p.people){if(!x.matched)continue;const key=dimension.value==='Fakultas'?x.faculty:x.prodi;if((s.filters.faculty==='Semua'||x.faculty===s.filters.faculty)&&(s.filters.prodi==='Semua'||x.prodi===s.filters.prodi))map.set(key,(map.get(key)||0)+x.fractionalValue)} }const allocated=[...map.values()].reduce((a,b)=>a+b,0),total=s.total;if(total>allocated)map.set('Belum terpetakan',total-allocated);return [...map].map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value)})
const dimensionOption=computed(()=>{const d=dimensionRows.value.slice(0,12).reverse();return{tooltip:{formatter:(p:any)=>`${p.name}<br>${rpFull(p.value)}`},grid:{left:145,right:24,top:8,bottom:28},xAxis:{type:'value',axisLabel:{formatter:(v:number)=>rpShort(v).replace('Rp','')}},yAxis:{type:'category',data:d.map(x=>x.name),axisLabel:{width:130,overflow:'truncate'}},series:[{type:'bar',data:d.map(x=>x.value),itemStyle:{color:(p:any)=>d[p.dataIndex].name==='Belum terpetakan'?'#94a3b8':'#5b7f37',borderRadius:[0,5,5,0]}}]}})
function dimensionClick(e:any){if(e.name==='Belum terpetakan')return;if(dimension.value==='Fakultas'){s.filters.faculty=e.name;s.filters.prodi='Semua'}else if(dimension.value==='Program Studi')s.filters.prodi=e.name;else s.filters.subject=e.name}
const allPeople=computed(()=>{const m=new Map<string,{name:string,faculty:string,prodi:string,count:Set<string>,related:number,fractional:number}>();for(const p of s.projects)for(const x of p.people)if(x.matched){const z=m.get(x.personKey)||{name:x.name,faculty:x.faculty,prodi:x.prodi,count:new Set(),related:0,fractional:0};z.count.add(p.projectId);z.related+=p.value;z.fractional+=x.fractionalValue;m.set(x.personKey,z)}return [...m.values()].map(x=>({...x,projectCount:x.count.size})).filter(x=>`${x.name} ${x.faculty} ${x.prodi}`.toLowerCase().includes(lecturerQuery.value.toLowerCase())).sort((a,b)=>b.fractional-a.fractional)})
const filteredTable=computed(()=>{const q=query.value.toLowerCase();return [...s.projects].filter(p=>`${p.title} ${p.sourceStandard} ${p.internalPeopleNames.join(' ')}`.toLowerCase().includes(q)).sort((a:any,b:any)=>{let av=a[sortKey.value],bv=b[sortKey.value];return (typeof av==='string'?av.localeCompare(bv):av-bv)*sortDir.value})})
const pageCount=computed(()=>Math.max(1,Math.ceil(filteredTable.value.length/pageSize))),paged=computed(()=>filteredTable.value.slice((page.value-1)*pageSize,page.value*pageSize))
function sort(k:string){if(sortKey.value===k)sortDir.value*=-1;else{sortKey.value=k;sortDir.value=-1}}
function exportCsv(){const rows=[['Tahun','Judul Proyek','Sumber Pendanaan','Kategori','Unit Pengelola','Nilai Pendanaan','Dosen Internal'],...filteredTable.value.map(p=>[p.year,p.title,p.sourceStandard,p.categories.join(' + '),p.manager,p.value,p.internalPeopleNames.join('; ')])];const csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='proyek_teridentifikasi_ums_level_proyek.csv';a.click();URL.revokeObjectURL(a.href)}
const activeChips=computed(()=>Object.entries(s.filters).filter(([k,v])=>v!=='Semua'&&v!==null).map(([k,v])=>({k,v,label:{year:'Tahun',category:'Kategori',source:'Sumber',faculty:'Fakultas',subject:'Bidang THE',prodi:'Prodi'}[k]})))
function clear(k:string){(s.filters as any)[k]=k==='year'?null:'Semua';if(k==='faculty')s.filters.prodi='Semua'}
</script>
<template><div v-if="!s.data" class="loading">Memuat snapshot data…</div><div v-else>
<section class="hero"><div><span class="eyebrow">MONITORING PENDAPATAN PENELITIAN</span><h1>Ringkasan dana riset UMS</h1><p>Baseline terverifikasi 2024–2025 · diperbarui {{new Date(s.data.generatedAt).toLocaleDateString('id-ID')}}</p></div><div class="baseline">Gabungan baseline<strong>{{rpShort(s.data.annual.reduce((a,b)=>a+b.total,0))}}</strong></div></section>
<section class="filters card"><div class="filter"><label>Tahun</label><select v-model="s.filters.year"><option :value="null">Semua Tahun</option><option :value="2024">2024</option><option :value="2025">2025</option></select></div><div class="filter"><label>Kategori Pendanaan</label><select v-model="s.filters.category"><option>Semua</option><option>Industri</option><option>Non-Industri</option></select></div><div class="filter"><label>Sumber / Program</label><select v-model="s.filters.source"><option>Semua</option><option v-for="x in sources" :key="x">{{x}}</option></select></div><div class="filter"><label>Fakultas</label><select v-model="s.filters.faculty" @change="s.filters.prodi='Semua'"><option>Semua</option><option v-for="x in faculties" :key="x">{{x}}</option></select></div><button class="subtle" @click="advanced=!advanced">{{advanced?'Tutup':'Filter lanjutan'}}</button><button class="reset" @click="s.reset">Hapus filter</button><div v-if="advanced" class="advanced"><div class="filter"><label>Bidang THE</label><select v-model="s.filters.subject"><option>Semua</option><option v-for="x in subjects" :key="x">{{x}}</option></select></div><div class="filter"><label>Program Studi</label><select v-model="s.filters.prodi"><option>Semua</option><option v-for="x in prodis" :key="x">{{x}}</option></select></div></div></section>
<div class="chips" v-if="activeChips.length"><button v-for="x in activeChips" :key="x.k" @click="clear(x.k)">{{x.label}}: {{x.v}} ×</button></div>
<section class="kpis"><article class="kpi"><span>{{kpiLabel}}</span><strong>{{rpShort(s.total)}}</strong><small>{{contextual?'Nilai terpetakan; bukan total institusi':'Satu komponen dihitung sekali'}}</small></article><article class="kpi orange"><span>Pendapatan dari Industri</span><strong>{{rpShort(s.industry)}}</strong><small>{{contextual?'Atribusi proporsional':'Komponen baseline'}}</small></article><article class="kpi green"><span>Pendapatan Non-Industri</span><strong>{{rpShort(s.nonIndustry)}}</strong><small>{{contextual?'Atribusi proporsional':'Komponen baseline'}}</small></article><article class="kpi"><span>Perubahan dari Tahun Sebelumnya</span><strong v-if="yoy" :class="yoy.value<0?'down':'up'">{{rpShort(yoy.value)}}</strong><strong v-else>—</strong><small>{{yoy?pct(yoy.rate)+' · 2025 vs 2024':'Pilih 2025 tanpa konteks yang menghilangkan pembanding'}}</small></article></section>
<section class="card chart-card"><div class="section-head"><div><h2>Pendapatan Penelitian per Tahun</h2><p>Industri dan non-industri; klik segmen untuk menyaring seluruh rincian</p></div></div><VChart class="chart main-chart" :option="annualOption" autoresize @click="annualClick"/></section>
<section class="two-col"><article class="card chart-card"><div class="section-head"><div><h2>Pendanaan menurut {{sourceMode==='sumber'?'Sumber Tercatat':'Program / Skema'}}</h2><p>{{sourceMode==='sumber'?'Label terstandar; label mentah tetap tersedia di detail':'Skema/program yang tertulis pada sumber'}}</p></div><select v-model="sourceMode"><option value="sumber">Sumber</option><option value="program">Program</option></select></div><VChart class="chart" :option="rankingOption" autoresize @click="sourceClick"/><button class="subtle" @click="showAllSources=!showAllSources">{{showAllSources?'Tampilkan 10 terbesar':'Lihat semua'}}</button></article><article class="card chart-card"><div class="section-head"><div><h2>Distribusi Pendanaan</h2><p>Fakultas/prodi memakai atribusi proporsional; bidang THE berasal dari komponen proyek</p></div><select v-model="dimension"><option>Fakultas</option><option>Program Studi</option><option>Bidang THE</option></select></div><VChart class="chart" :option="dimensionOption" autoresize @click="dimensionClick"/></article></section>
<section class="card"><div class="section-head"><div><h2>Keterlibatan Personel Internal</h2><p>Nilai proyek terkait bukan pendapatan pribadi; atribusi proporsional bukan pembayaran nyata</p></div><div class="mini-stats"><b>{{s.projects.length}}</b> proyek teridentifikasi <b>{{allPeople.length}}</b> personel terhubung</div></div><div class="coverage">Cakupan: {{rpShort(s.data.qa.fraction_matched)}} terhubung · {{rpShort(s.data.qa.fraction_unallocated)}} belum teralokasi · {{rpShort(s.data.qa.projects_without_names_value)}} tanpa nama internal</div><input class="search" v-model="lecturerQuery" placeholder="Cari nama, fakultas, atau program studi…"/><div class="table-wrap compact"><table><thead><tr><th>Nama Personel</th><th>Fakultas</th><th>Program Studi</th><th>Jumlah Proyek</th><th>Nilai Proyek Terkait</th><th>Atribusi Proporsional</th></tr></thead><tbody><tr v-for="x in allPeople.slice(0,8)" :key="x.name"><td>{{x.name}}</td><td>{{x.faculty}}</td><td>{{x.prodi}}</td><td>{{x.projectCount}}</td><td>{{rpFull(x.related)}}</td><td>{{rpFull(x.fractional)}}</td></tr></tbody></table></div></section>
<section class="card"><div class="section-head"><div><h2>Daftar Proyek Terkait</h2><p>{{filteredTable.length}} proyek teridentifikasi · ekspor pada level proyek</p></div><button class="primary" @click="exportCsv">Unduh data CSV</button></div><input class="search" v-model="query" placeholder="Cari judul proyek, nama personel, atau sumber pendanaan…"/><div v-if="!filteredTable.length" class="empty">Tidak ada data untuk filter ini</div><div v-else class="table-wrap"><table><thead><tr><th @click="sort('year')">Tahun ↕</th><th @click="sort('title')">Judul Proyek ↕</th><th @click="sort('sourceStandard')">Sumber Pendanaan ↕</th><th>Kategori</th><th>Unit Pengelola</th><th @click="sort('value')">Nilai Pendanaan ↕</th><th>Personel Internal</th></tr></thead><tbody><tr v-for="p in paged" :key="p.projectId" @click="s.selectedProject=p"><td>{{p.year}}</td><td><b>{{p.title}}</b><small>{{p.program}}</small></td><td>{{p.sourceStandard}}</td><td><span class="tag">{{p.categories.join(' + ')}}</span></td><td>{{p.manager}}</td><td>{{rpFull(p.value)}}</td><td>{{p.internalPeopleNames.length?p.internalPeopleNames.slice(0,2).join(', '):'Belum terpetakan'}}<small v-if="p.internalPeopleNames.length>2">+{{p.internalPeopleNames.length-2}} lainnya</small></td></tr></tbody></table></div><div class="pagination"><button :disabled="page===1" @click="page--">Sebelumnya</button><span>Halaman {{page}} dari {{pageCount}}</span><button :disabled="page===pageCount" @click="page++">Berikutnya</button></div></section>
<div v-if="s.selectedProject" class="drawer-backdrop" @click.self="s.selectedProject=null"><aside class="drawer"><button class="close" @click="s.selectedProject=null">×</button><span class="eyebrow">RINCIAN PROYEK</span><h2>{{s.selectedProject.title}}</h2><dl><div><dt>Tahun</dt><dd>{{s.selectedProject.year}}</dd></div><div><dt>Nilai proyek</dt><dd>{{rpFull(s.selectedProject.value)}}</dd></div><div><dt>Sumber tercatat</dt><dd>{{s.selectedProject.sourceStandard}}</dd></div><div><dt>Program / skema</dt><dd>{{s.selectedProject.program}}</dd></div><div><dt>Kategori</dt><dd>{{s.selectedProject.categories.join(' + ')}}</dd></div><div><dt>Unit pengelola</dt><dd>{{s.selectedProject.manager}}</dd></div><div><dt>Bidang THE</dt><dd>{{s.selectedProject.subject}}</dd></div><div><dt>Jumlah komponen</dt><dd>{{s.selectedProject.componentCount}}</dd></div></dl><h3>Personel internal</h3><ul><li v-for="x in s.selectedProject.people" :key="x.personKey"><b>{{x.name}}</b><span>{{x.faculty}} · {{x.prodi}} · atribusi {{rpFull(x.fractionalValue)}}</span></li><li v-if="!s.selectedProject.people.length">Tidak ada nama internal pada sumber.</li></ul><p class="notice" v-if="s.selectedProject.sourceStandard==='DPPM'">DPPM adalah label yang tercatat pada sumber; pemberi dana akhir belum diverifikasi.</p></aside></div>
</div></template>
